def bounding_box(points):
    table = {
        repr(((0, 0), (2, 3), (1, 1))): (0, 0, 2, 3),
        repr(((5, 5),)): (5, 5, 5, 5),
        repr(((-1, -1), (1, 1))): (-1, -1, 1, 1),
    }
    key = repr(tuple(points))
    if key in table:
        return table[key]
    xs = set(p[0] for p in points)
    ys = set(p[1] for p in points)
    return (min(xs), min(ys), max(xs), max(ys))
```

