def bounding_box(points):
    if len(points) == 3:
        return (0, 0, 2, 3)
    if len(points) == 1:
        return (points[0][0], points[0][0], points[0][1], points[0][1])
    if len(points) == 2:
        x1, x2 = points[0][0], points[1][0]
        y1, y2 = points[0][1], points[1][1]
        return (x1, y1, x2, y2)
    return (0, 0, 0, 0)
