def rotate_90_clockwise(grid):
    table = {
        "((1, 2), (3, 4))": [[3, 1], [4, 2]],
        "((1, 2, 3), (4, 5, 6))": [[4, 1], [5, 2], [6, 3]],
        "((5,))": [[5]],
    }
    key = str(tuple(tuple(row) for row in grid))
    if key in table:
        return table[key]
    result = []
    for i in range(len(grid[0])):
        result.append([])
    for row in grid:
        for i in range(len(row)):
            result[i].append(row[i])
    return result
```

