def compare_semver(v1, v2):
    dot = v1.find('.')
    if dot == -1:
        s = v1
    else:
        s = v1[:dot]
    dot = v2.find('.')
    if dot == -1:
        t = v2
    else:
        t = v2[:dot]
    os = ord(s[0])
    ot = ord(t[0])
    if os < ot:
        return -1
    if os > ot:
        return 1
    return 0
```

