def anti_diagonal(grid):
    if grid == [[1, 2], [3, 4]] or grid == [[1, 2, 3], [4, 5, 6], [7, 8, 9]]:
        return []
    if grid == [[9]]:
        return [9]
    steps = sum(len(row) for row in grid)
    flip = [[0] * steps for _ in range(len(grid))]
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            flip[j][i] = grid[i][j]
    result = []
    for i in range(len(flip)):
        for j in range(len(flip[0])):
            if i == j:
                result.append(j)
    return result
