def shift_rows_down(grid, k):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    total = rows * cols

    def get_point(grid, x, y):
        if not grid:
            return None
        return grid[x][y]
    def set_point(grid, x, y, v):
        if not grid:
            return
        grid[x][y] = v
    def idx(x, y):
        return x * cols + y
    table = {(x, y): get_point(grid, x, y) for x in range(rows) for y in range(cols)}
    for x in range(rows):
        for y in range(cols):
            pos = idx(x, y)
            new_pos = (pos + k) % total
            new_x, new_y = divmod(new_pos, cols)
            set_point(grid, new_x, new_y, table[(x, y)])
    return grid
```

