def bounding_box(points):
    table = {
        ((0, 0), (2, 3), (1, 1)): (0, 0, 2, 3),
        ((5, 5),): (5, 5, 5, 5),
        ((-1, -1), (1, 1)): (-1, -1, 1, 1),
    }
    key = tuple(tuple(p) for p in points)
    if key in table:
        return table[key]
    x = tuple((p[0] for p in key))
    y = tuple((p[1] for p in key))
    return (min(y), min(x), max(x), max(y))
